function App() {
  const items = useCollection("items");
  const [name, setName] = useState("");

  function add(e) {
    e.preventDefault();
    if (name.trim() === "") return;
    items.add({ name: name.trim(), done: false });
    setName("");
  }

  return (
    <Page title="Shopping">
      <Card>
        <form onSubmit={add}>
          <Row gap={8} align="end">
            <Input label="Item" value={name} onChange={e => setName(e.target.value)} />
            <Button>Add</Button>
          </Row>
        </form>
      </Card>
      <Card title="To buy">
        {items.items.length === 0 ? <Empty>Nothing to buy.</Empty> : (
          <Stack gap={8}>
            {items.items.map(i => (
              <Row key={i.id} gap={8} align="center" justify="between">
                <Checkbox label={i.name} checked={i.done} onChange={e => items.update(i.id, { done: e.target.checked })} />
                <Button small variant="danger" onClick={() => items.remove(i.id)}>Delete</Button>
              </Row>
            ))}
          </Stack>
        )}
      </Card>
    </Page>
  );
}

